public class Rectangle {
    private double length;      // instance variable, belongs to the object
    private double width;       // instance variable

    public double area() {
        double result = length * width;   // local variable, exists only during this call
        return result;
    }

    public void describe() {
        // System.out.println(result);    // error: result does not exist here
        System.out.println("Rectangle " + length + " x " + width);
    }
}

public class Student {
    private String name;

    public void setName(String name) {
        this.name = name;      // this.name is the instance variable; name is the parameter
    }
}

public class Rectangle {
    private double length;
    private double width;

    public Rectangle(double length, double width) {
        this.length = length;
        this.width = width;
    }

    public String toString() {
        return "Rectangle " + length + " x " + width;
    }
}

